using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    public void add_file_shader_uniforms(Control owner,Resource data,VBoxContainer parent)
    {
        var source=_data.object_get_value(data,"shader_path","");if(source.VariantType==Variant.Type.Nil||source.VariantType==Variant.Type.String&&source.AsString().Length==0){add_label(parent,"Choose a .gdshader file to expose its uniforms.");return;}var shader=shader_from_value(source);if(shader==null){add_label(parent,"The selected shader could not be loaded.");return;}int shown=0;foreach(var entry in shader_uniform_layout(owner,shader,parent,"FileResource:"+data.ResourcePath,"ShaderUniforms")){var info=entry["info"].AsGodotDictionary();string name=info.GetValueOrDefault("name","").AsString();if(name.Length==0)continue;var fallback=shader_uniform_default(shader,name,info.GetValueOrDefault("type",0).AsInt32());var stored=_data.object_get_value(data,"uniforms",new Settings()).AsGodotDictionary();add_file_shader_uniform_value(owner,data,entry["parent"].As<VBoxContainer>(),name,stored.GetValueOrDefault(new StringName(name),fallback),fallback,info);shown++;}if(shown==0)add_label(parent,"This shader has no editable uniforms.");
    }
    public void set_file_uniform(Control owner,Resource data,StringName name,Variant value,string mode,Variant original)
    {
        var before=_data.object_get_value(data,"uniforms",new Settings()).AsGodotDictionary().Duplicate(true);var after=before.Duplicate(true);after[name]=_data.copy_value(value);var model=Ui<RefCounted>(owner,"model");if(mode=="preview"){_data.set_value(data,"uniforms",after);model.EmitSignal("changed");return;}if(mode=="commit"&&original.VariantType==Variant.Type.Dictionary)before=original.AsGodotDictionary().Duplicate(true);if(same_value(before,after))return;var action=new InspectorFilePropertyAction(model,data,data,data,"uniforms",before,after);var history=model.Get("history").As<UndoRedo>();history.CreateAction("Change "+name.ToString().Capitalize());history.AddDoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_before)));history.AddDoReference(action);history.CommitAction();
    }
    public void add_file_shader_uniform_value(Control owner,Resource data,VBoxContainer parent,StringName name,Variant value,Variant fallback,Settings info)
    {
        int type=info.GetValueOrDefault("type",(int)fallback.VariantType).AsInt32();var defaultValue=type==(int)Variant.Type.Object?Variant.From(""):fallback;var heading=new HBoxContainer();parent.AddChild(heading);string title=name.ToString().Capitalize();heading.AddChild(new Label{Text=title,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var reset=new Button{Name=name+"_reset",Text="↺",Visible=!same_value(value,defaultValue)};heading.AddChild(reset);Settings Current()=>_data.object_get_value(data,"uniforms",new Settings()).AsGodotDictionary();void Set(Variant updated){set_file_uniform(owner,data,name,updated,"edit",default);reset.Visible=!same_value(updated,defaultValue);if(type==(int)Variant.Type.Object)owner.CallDeferred("inspect_file_resource",data.ResourcePath);}reset.Pressed+=()=>{Set(defaultValue);if(data.ResourcePath.Length>0)owner.CallDeferred("inspect_file_resource",data.ResourcePath);};void Wire(SpinBox input,Func<double,Variant> make){var origin=Current().Duplicate(true);input.Connect("interaction_started",Callable.From(()=>origin=Current().Duplicate(true)));input.Connect("preview_changed",Callable.From<double>(n=>set_file_uniform(owner,data,name,make(n),"preview",default)));input.Connect("drag_committed",Callable.From<double>(n=>set_file_uniform(owner,data,name,make(n),"commit",origin)));input.Connect("drag_cancelled",Callable.From(()=>{_data.set_value(data,"uniforms",origin.Duplicate(true));Ui<RefCounted>(owner,"model").EmitSignal("changed");}));input.ValueChanged+=n=>Set(make(n));}
        switch((Variant.Type)type){case Variant.Type.Int:case Variant.Type.Float:var property=_properties.create(name,title,defaultValue,true);var options=property.Get("options").AsGodotDictionary();options["step"]=.01;var parts=info.GetValueOrDefault("hint_string","").AsString().Split(',');if(info.GetValueOrDefault("hint",0).AsInt32()==(int)PropertyHint.Range&&parts.Length>=2){options["min"]=parts[0].ToFloat();options["max"]=parts[1].ToFloat();}var input=number_editor(owner,parent,value.AsDouble(),property);Wire(input,n=>type==(int)Variant.Type.Int?Variant.From((long)n):Variant.From(n));break;
        case Variant.Type.Bool:var toggle=new CheckButton{ButtonPressed=value.AsBool()};parent.AddChild(toggle);toggle.Toggled+=n=>Set(n);break;
        case Variant.Type.Vector2:case Variant.Type.Vector3:case Variant.Type.Vector4:case Variant.Type.Vector2I:case Variant.Type.Vector3I:case Variant.Type.Vector4I:bool integer=(Variant.Type)type is Variant.Type.Vector2I or Variant.Type.Vector3I or Variant.Type.Vector4I;for(int i=0;i<_timeline.component_count(value);i++){int axis=i;var numeric=number(owner,ActorAnimationOperations.Component(value,axis).AsDouble(),.01);numeric.Name=name+"_"+axis;Wire(numeric,n=>ActorAnimationOperations.WithComponent(_data.copy_value(Current().GetValueOrDefault(name,value)),axis,integer?Variant.From((long)n):Variant.From(n)));parent.AddChild(numeric);}break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Color=value.AsColor();parent.AddChild(color);var before=Current().Duplicate(true);color.Connect("interaction_started",Callable.From(()=>before=Current().Duplicate(true)));color.Connect("preview_changed",Callable.From<Color>(n=>set_file_uniform(owner,data,name,n,"preview",default)));color.Connect("drag_committed",Callable.From<Color,Color>((_,n)=>set_file_uniform(owner,data,name,n,"commit",before)));color.Connect("drag_cancelled",Callable.From<Color>(_=>{_data.set_value(data,"uniforms",before.Duplicate(true));Ui<RefCounted>(owner,"model").EmitSignal("changed");}));break;
        case Variant.Type.Object:owner.Call("_add_file_uniform_texture",data,parent,name,title);break;
        default:var text=new LineEdit{Text=GD.VarToStr(value),TooltipText="Edit this value using Godot Variant syntax, then press Enter."};text.TextSubmitted+=n=>{var parsed=GD.StrToVar(n);if((int)parsed.VariantType==type)Set(parsed);};parent.AddChild(text);break;}
    }
}
